CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, student_id TEXT NOT NULL UNIQUE, faculty TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'student');
CREATE TABLE IF NOT EXISTS articles (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), title TEXT NOT NULL, category TEXT NOT NULL, faculty TEXT NOT NULL DEFAULT 'Faculty of Computing', body TEXT NOT NULL, image TEXT NOT NULL DEFAULT 'images/research.jpg', format TEXT NOT NULL DEFAULT 'Article', status TEXT NOT NULL DEFAULT 'pending', feedback TEXT NOT NULL DEFAULT '', expires TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookmarks (user_id INTEGER REFERENCES users(id), article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,article_id));
CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), article_id INTEGER REFERENCES articles(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS preferences (user_id INTEGER PRIMARY KEY REFERENCES users(id), categories TEXT NOT NULL DEFAULT '["Academic","Events"]', notifications TEXT NOT NULL DEFAULT '1');

CREATE TABLE IF NOT EXISTS recovery_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS recovery_pending_user ON recovery_requests(user_id) WHERE status='pending';
